ve_source_ids',active_ids,'refunded_source_ids',refunded_ids,'payable',false);\nEND $function$\n","metadata":{"oid":"34785529","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13573","proname":"fn_accounting_tournament_fee_net_plan","prorows":0,"pronargs":1,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_tournament_id"],"proargtypes":["2950"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"fn_accounting_tournament_fee_fingerprint(rake_records)","definition":"CREATE OR REPLACE FUNCTION public.fn_accounting_tournament_fee_fingerprint(p_row rake_records)\n RETURNS text\n LANGUAGE sql\n IMMUTABLE\n SET search_path TO 'public'\nAS $function$\n -- Versioned economic fields are stable across unrelated schema additions.\n -- Tuple terminal markers are not economic source edits.\n SELECT md5(jsonb_build_object('id',p_row.id,'hand_id',p_row.hand_id,'table_id',p_row.table_id,'club_id',p_row.club_id,'rake_amount',p_row.rake_amount,'bbj_contribution',p_row.bbj_contribution,'pot_size',p_row.pot_size,'num_players',p_row.num_players,'created_at',p_row.created_at,'player_contributions',p_row.player_contributions,'global_hand_id',p_row.global_hand_id,'is_tournament',p_row.is_tournament,'tournament_id',p_row.tournament_id,'source',p_row.source,'metadata',p_row.metadata,'rake_method',p_row.rake_method,'returned_uncalled',p_row.returned_uncalled)::text)\n$function$\n","metadata":{"oid":"34785501","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"fn_accounting_tournament_fee_fingerprint","prorows":0,"pronargs":1,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":false,"prorettype":"25","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_row"],"proargtypes":["123163"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"i","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"public.fn_union_pnl_touched_registrations(timestamp with time zone,timestamp with time zone,boolean)","definition":"CREATE OR REPLACE FUNCTION public.fn_union_pnl_touched_registrations(p_start timestamp with time zone, p_end timestamp with time zone, p_projected boolean)\n RETURNS TABLE(registration_id uuid, touched_tournament_id text)\n LANGUAGE sql\n STABLE\nAS $function$\n SELECT i.row_id,i.tournament_id FROM public.union_pnl_inventory_touches i\n WHERE p_projected IS TRUE AND i.source_name OPERATOR(pg_catalog.=) 'tournament_players'::pg_catalog.text\n AND i.frame_observed_at OPERATOR(pg_catalog.>=) p_start AND i.frame_observed_at OPERATOR(pg_catalog.<) p_end\n AND i.observed_at OPERATOR(pg_catalog.>=) p_start AND i.observed_at OPERATOR(pg_catalog.<) p_end\n UNION ALL\n SELECT i.row_id,COALESCE(i.after_row,i.before_row) OPERATOR(pg_catalog.->>) 'tournament_id'::pg_catalog.text\n FROM public.union_pnl_inventory_events i JOIN public.union_pnl_transaction_frames b ON b.transaction_id OPERATOR(pg_catalog.=) i.transaction_id\n WHERE p_projected IS NOT TRUE AND i.source_name OPERATOR(pg_catalog.=) 'tournament_players'::pg_catalog.text\n AND b.observed_at OPERATOR(pg_catalog.>=) p_start AND b.observed_at OPERATOR(pg_catalog.<) p_end\n AND i.observed_at OPERATOR(pg_catalog.>=) p_start AND i.observed_at OPERATOR(pg_catalog.<) p_end\n$function$\n","metadata":{"oid":"69681147","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"fn_union_pnl_touched_registrations","prorows":1000,"pronargs":3,"proowner":"16384","proconfig":null,"proretset":true,"prosecdef":false,"prorettype":"2249","prosqlbody":null,"prosupport":"-","proargmodes":["i","i","i","t","t"],"proargnames":["p_start","p_end","p_projected","registration_id","touched_tournament_id"],"proargtypes":["1184","1184","16"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"2200","proallargtypes":["1184","1184","16","2950","25"],"proargdefaults":null,"pronargdefaults":0}},{"signature":"public.fn_union_pnl_tournament_entry_club_of(text,numeric,uuid,uuid,uuid,jsonb)","definition":"CREATE OR REPLACE FUNCTION public.fn_union_pnl_tournament_entry_club_of(p_asset text, p_amount numeric, p_funding_club_id uuid, p_ledger_id uuid, p_entitlement_id uuid, p_registration_snapshot jsonb)\n RETURNS uuid\n LANGUAGE sql\n IMMUTABLE\nAS $function$\n SELECT CASE WHEN p_asset OPERATOR(pg_catalog.=) 'chips'::pg_catalog.text AND p_amount OPERATOR(pg_catalog.>) 0::pg_catalog.numeric THEN p_funding_club_id\n WHEN p_asset OPERATOR(pg_catalog.=) 'chips'::pg_catalog.text AND p_amount OPERATOR(pg_catalog.=) 0::pg_catalog.numeric\n AND p_ledger_id IS NULL AND p_entitlement_id IS NULL\n AND (p_registration_snapshot OPERATOR(pg_catalog.->>) 'source_satellite_id'::pg_catalog.text) IS NULL\n AND (p_registration_snapshot OPERATOR(pg_catalog.->) 'is_satellite_qualifier'::pg_catalog.text) OPERATOR(pg_catalog.=) 'false'::pg_catalog.jsonb\n THEN (p_registration_snapshot OPERATOR(pg_catalog.->>) 'club_id'::pg_catalog.text)::pg_catalog.uuid END;\n$function$\n","metadata":{"oid":"69681188","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"fn_union_pnl_tournament_entry_club_of","prorows":0,"pronargs":6,"proowner":"16384","proconfig":null,"proretset":false,"prosecdef":false,"prorettype":"2950","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_asset","p_amount","p_funding_club_id","p_ledger_id","p_entitlement_id","p_registration_snapshot"],"proargtypes":["25","1700","2950","2950","2950","3802"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"i","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"signature":"public.fn_union_pnl_week_shaped_hands(uuid,timestamp with time zone,timestamp with time zone,boolean)","definition":"CREATE OR REPLACE FUNCTION public.fn_union_pnl_week_shaped_hands(p_union_id uuid, p_start timestamp with time zone, p_end timestamp with time zone, p_projected boolean)\n RETURNS SETOF union_pnl_cash_outcomes\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nBEGIN\n IF p_projected THEN\n  RETURN QUERY WITH touch_keys AS MATERIALIZED (SELECT h.table_id,h.hand_number FROM public.union_pnl_cash_outcome_touches h WHERE h.game_union_id=p_union_id::text AND h.recognized_at>=p_start AND h.recognized_at<p_end AND h.shaped IS TRUE) SELECT o.* FROM touch_keys k CROSS JOIN LATERAL(SELECT q.* FROM public.union_pnl_cash_outcomes q WHERE q.table_id=k.table_id AND q.hand_number=k.hand_number AND q.game_scope->>'game_union_id'=p_union_id::text AND q.recognized_at>=p_start AND q.recognized_at<p_end AND (q.evidence->>'status' IS DISTINCT FROM 'ready' OR q.evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb\n     OR q.evidence->'all_players_included' IS DISTINCT FROM 'true'::jsonb OR q.evidence->'game_scope' IS DISTINCT FROM q.game_scope) OFFSET 0)o;\n ELSE\n  RETURN QUERY SELECT o.* FROM public.union_pnl_cash_outcomes o WHERE o.game_scope->>'game_union_id'=p_union_id::text AND o.recognized_at>=p_start AND o.recognized_at<p_end\n   AND (o.evidence->>'status' IS DISTINCT FROM 'ready' OR o.evidence->'basis_certified' IS DISTINCT FROM 'true'::jsonb\n    OR o.evidence->'all_players_included' IS DISTINCT FROM 'true'::jsonb OR o.evidence->'game_scope' IS DISTINCT FROM o.game_scope);\n END IF;\nEND $function$\n","metadata":{"oid":"69681167","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13573","proname":"fn_union_pnl_week_shaped_hands","prorows":1000,"pronargs":4,"proowner":"16384","proconfig":["search_path=public, pg_temp"],"proretset":true,"prosecdef":true,"prorettype":"35411232","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_union_id","p_start","p_end","p_projected"],"proargtypes":["2950","1184","1184","16"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0}},{"metadata":{"oid":"34785319","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"13573","proname":"fn_prepare_accounting_week","prorows":0,"pronargs":4,"proowner":"16384","proconfig":["search_path=public"],"proretset":false,"prosecdef":true,"prorettype":"3802","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":["p_union_id","p_club_id","p_from","p_to"],"proargtypes":["2950","2950","1184","1184"],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"v","proleakproof":false,"pronamespace":"2200","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"signature":"public.fn_prepare_accounting_week(uuid,uuid,timestamp with time zone,timestamp with time zone)","definition":"CREATE OR REPLACE FUNCTION public.fn_prepare_accounting_week(p_union_id uuid, p_club_id uuid, p_from timestamp with time zone, p_to timestamp with time zone)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE clubs uuid[];club uuid;result jsonb;problems jsonb:='[]';from_date date;to_date date;ready boolean;verified boolean;source_check jsonb;refusal_key text;\nBEGIN\n IF NOT public.fn_caller_is_engine() THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;\n IF p_from IS NULL OR p_to IS NULL OR NOT isfinite(p_from) OR NOT isfinite(p_to)\n  OR p_from IS DISTINCT FROM public.fn_union_week_start(p_from)\n  OR p_to IS DISTINCT FROM public.fn_union_week_start(p_from+interval '8 days') OR p_to>now()\n THEN RAISE EXCEPTION 'accounting_preparation_requires_closed_week' USING ERRCODE='22023'; END IF;\n from_date:=(p_from AT TIME ZONE 'America/Los_Angeles')::date;to_date:=(p_to AT TIME ZONE 'America/Los_Angeles')::date-1;\n IF (p_union_id IS NULL)=(p_club_id IS NULL) THEN RAISE EXCEPTION 'invalid_accounting_scope' USING ERRCODE='22023'; END IF;\n IF p_union_id IS NOT NULL THEN PERFORM public.fn_union_pnl_closed_book_barrier(p_to); END IF;\n PERFORM pg_advisory_xact_lock(hashtextextended(\n  CASE WHEN p_union_id IS NOT NULL THEN 'union-accounting:' ELSE 'club-accounting:' END\n   ||COALESCE(p_union_id,p_club_id)::text||':'||extract(epoch FROM p_from)::text||':'||extract(epoch FROM p_to)::text,0));\n -- The source queue is part of this book. Check it under the same week lock,\n -- before discovery, payer locks, calculations, or any financial stage.\n -- ONE REFUSAL CHECK PER ATTEMPT (20261003): inside one union close attempt\n -- (app.accounting_close_memo='on', set only by fn_weekly_accounting_attempt_begin,\n -- cleared by it and by attempt_end) the cascade's preparation repeats the\n -- scheduler's, for the same book, under this same week lock, which the\n -- attempt has held since. A 'ready' answer of this attempt is reused there;\n -- anything else, and every call outside an attempt, asks the queue as before.\n refusal_key:=COALESCE(p_union_id,p_club_id)::text||'|'||p_from::text||'|'||p_to::text;\n IF current_setting('app.accounting_close_memo',true)='on'\n  AND current_setting('app.accounting_cash_refusal_memo',true)=refusal_key THEN\n  source_check:=jsonb_build_object('status','ready','count',0,'sources','[]'::jsonb);\n ELSE\n  source_check:=public.fn_cash_source_refusals_for_period(p_union_id,p_club_id,p_from,p_to);\n  IF current_setting('app.accounting_close_memo',true)='on' AND source_check->>'status'='ready'\n   AND source_check->'count'='0'::jsonb AND source_check->'sources'='[]'::jsonb THEN\n   PERFORM set_config('app.accounting_cash_refusal_memo',refusal_key,true);\n  END IF;\n END IF;\n IF source_check->>'status' IS DISTINCT FROM 'ready'\n  OR source_check->'count' IS DISTINCT FROM '0'::jsonb\n  OR source_check->'sources' IS DISTINCT FROM '[]'::jsonb THEN\n  RETURN jsonb_build_object('success',false,'accounting_version',3,\n   'union_id',p_union_id,'club_id',p_club_id,'period_start',p_from,'period_end',p_to,'clubs',0,\n   'problems',jsonb_build_array(jsonb_build_object('reason','cash_source_refusals_pending',\n    'source_check',source_check)));\n END IF;\n -- The original R0 transition qualifies historical interpretation before any\n -- source-plan reuse or payer stage. Each bounded batch commits no money.\n source_check:=smarter_private.prepare_own_agent_interpretation(p_union_id,p_club_id,p_from,p_to);\n IF source_check->>'ready'IS DISTINCT FROM'true'THEN\n  RETURN jsonb_build_object('success',false,'accounting_version',3,'union_id',p_union_id,'club_id',p_club_id,'period_start',p_from,'period_end',p_to,'clubs',0,'problems',jsonb_build_array(jsonb_build_object('reason','own_agent_source_interpretation_in_progress','source_check',source_check)));\n END IF;\n -- Rakeback is due before club-book settlement (owner, 2026-10-26).\n -- Keep the closed book, source queue, recorded contracts and calculation\n -- receipts here. The original cascade proves P&L after its conserved paid\n -- rounds, before any club period is settled or weekly invoice is issued.\n -- The fee windows belong to fee preparation, before later club books.\n -- Only enter the original advance when its fee prefix has missing work:\n -- that prefix ends its attempt before any P&L branch. Its proof, IDs, row\n -- hashes, refusal path and unchanged time budget remain authoritative.\n IF p_union_id IS NOT NULL\n  AND COALESCE(current_setting('app.weekly_accounting_chunked',true),'')='on'\n  AND current_setting('app.accounting_close_memo',true)='on'\n  AND NULLIF(current_setting('app.weekly_accounting_scope_deadline',true),'') IS NOT NULL\n  AND EXISTS(SELECT FROM public.accounting_cash_accrual_cutover WHERE singleton AND starts_at<=p_from)\n  AND NOT EXISTS(SELECT FROM public.accounting_routed_settlement_runs r\n   WHERE r.scope_kind='union' AND r.scope_id=p_union_id AND r.round_no=3\n    AND r.period_start=p_from AND r.period_end=p_to)\n  AND public.fn_accounting_close_certificate('earned_plan',p_union_id,p_from,p_to) IS NULL\n  AND EXISTS(SELECT FROM public.fn_accounting_close_windows(p_from,p_to) w\n   WHERE NOT EXISTS(SELECT FROM public.accounting_close_partials p\n    WHERE p.kind='earned_plan_window' AND p.union_id=p_union_id\n     AND p.period_start=p_from AND p.period_end=p_to\n     AND p.window_start=w.window_start AND p.window_end=w.window_end\n     AND p.computed_at>=p_to\n     AND p.computed_at>clock_timestamp()-public.fn_accounting_close_proof_lifetime())) THEN\n  IF public.fn_accounting_union_earned_plan_advance(p_union_id,p_from,p_to) IS DISTINCT FROM false THEN\n   RAISE EXCEPTION 'earned_fee_window_advance_did_not_stop_after_fee_work' USING ERRCODE='55000';\n  END IF;\n  RETURN jsonb_build_object('success',false,'accounting_version',3,\n   'union_id',p_union_id,'club_id',p_club_id,'period_start',p_from,'period_end',p_to,'clubs',0,\n   'problems',jsonb_build_array(jsonb_build_object('reason','earned_fee_certification_in_progress')));\n END IF;\n SELECT COALESCE(array_agg(c.club_id ORDER BY c.club_id),ARRAY[]::uuid[]) INTO clubs\n  FROM public.fn_accounting_week_clubs(p_union_id,p_club_id,p_from,p_to)c;\n -- Same order as the routing stages, before Round 1 takes any treasury row.\n PERFORM public.fn_lock_rakeback_payer_clubs(clubs);\n IF p_union_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r\n    WHERE r.scope_kind='union' AND r.scope_id=p_union_id AND r.round_no=3\n     AND r.period_start=p_from AND r.period_end=p_to) THEN\n  -- CHUNKED CLOSE (20261003): inside a chunked attempt (job 272 sets\n  -- app.weekly_accounting_chunked) a round 3 an earlier attempt committed is\n  -- answered from its own receipt, as the cascade answers it, instead of\n  -- reading the whole week again to prove it a duplicate.\n  IF COALESCE(current_setting('app.weekly_accounting_chunked',true),'')='on' THEN\n   SELECT r.result||jsonb_build_object('duplicate',true) INTO source_check FROM public.accounting_routed_settlement_runs r\n    WHERE r.scope_kind='union' AND r.scope_id=p_union_id AND r.round_no=3 AND r.period_start=p_from AND r.period_end=p_to;\n  ELSE\n  source_check:=public.fn_settle_accounting_rakeback_stage('union',p_union_id,p_from,p_to);\n  END IF;\n  IF source_check->>'success' IS DISTINCT FROM 'true' OR source_check->>'duplicate' IS DISTINCT FROM 'true' THEN\n   RAISE EXCEPTION 'original_paid_scope_replay_not_confirmed' USING ERRCODE='55000'; END IF;\n  RETURN jsonb_build_object('success',true,'accounting_version',3,'union_id',p_union_id,'club_id',p_club_id,\n    'period_start',p_from,'period_end',p_to,'clubs',cardinality(clubs),'problems','[]'::jsonb,'paid_scope_replay',true);\n END IF;\n  -- A completed standalone R3 is its original paid-book authority, just as\n  -- the union replay above and typed R0 legacy-paid owner already require.\n  -- Retain every preceding source/refusal/interpretation/discovery/lock gate.\n  -- Only complete, exact-scope original R2/R3 receipts may avoid recalculation;\n  -- the coordinator still validates both receipts before accounting documents.\n  IF p_club_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r\n     WHERE r.scope_kind='club' AND r.scope_id=p_club_id AND r.round_no=3\n      AND r.period_start=p_from AND r.period_end=p_to) THEN\n   IF COALESCE(current_setting('app.weekly_accounting_chunked',true),'')='on' THEN\n    SELECT r.result||jsonb_build_object('duplicate',true) INTO source_check\n     FROM public.accounting_routed_settlement_runs r\n     WHERE r.scope_kind='club' AND r.scope_id=p_club_id AND r.round_no=3\n      AND r.period_start=p_from AND r.period_end=p_to;\n   ELSE\n    source_check:=public.fn_settle_accounting_rakeback_stage('club',p_club_id,p_from,p_to);\n   END IF;\n   IF source_check->>'success' IS DISTINCT FROM 'true' OR source_check->>'duplicate' IS DISTINCT FROM 'true'\n    OR source_check->>'routing_version' IS DISTINCT FROM '3' OR source_check->>'source_version' IS DISTINCT FROM '2'\n    OR source_check->'shortfalls' IS DISTINCT FROM '0'::jsonb\n    OR NOT EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r\n     WHERE r.scope_kind='club' AND r.scope_id=p_club_id AND r.round_no=3\n      AND r.period_start=p_from AND r.period_end=p_to AND r.completed_at IS NOT NULL\n      AND r.result=(source_check-'duplicate'))\n    OR NOT EXISTS(SELECT 1 FROM public.accounting_routed_settlement_runs r\n     WHERE r.scope_kind='club' AND r.scope_id=p_club_id AND r.round_no=2\n      AND r.period_start=p_from AND r.period_end=p_to AND r.completed_at IS NOT NULL\n      AND r.result->>'success'='true' AND r.result->>'routing_version'='3'\n      AND r.result->>'source_version'='2' AND r.result->'shortfalls'='0'::jsonb) THEN\n    RAISE EXCEPTION 'original_paid_scope_replay_not_confirmed' USING ERRCODE='55000'; END IF;\n   RETURN jsonb_build_object('success',true,'accounting_version',3,'union_id',p_union_id,'club_id',p_club_id,\n     'period_start',p_from,'period_end',p_to,'clubs',cardinality(clubs),'problems','[]'::jsonb,'paid_scope_replay',true);\n  END IF;\n FOREACH club IN ARRAY clubs LOOP\n  -- Reuse a receipt that is proven current (20260928233000): complete, ready,\n  -- not superseded by a later request, and no earning source of this club\n  -- for this week recorded after it. Rounds 2 and 3 re-verify certificates.\n  IF EXISTS(SELECT 1 FROM public.accounting_period_recompute_requests q\n    WHERE q.club_id=club AND q.period_start=from_date AND q.period_end=to_date\n     AND q.status='complete' AND q.attempted_at IS NOT NULL\n     AND q.last_requested_at<=q.attempted_at\n     AND q.last_result->>'accounting_version'='2' AND q.last_result->>'status'='ready'\n     AND q.last_result->>'club_id'=club::text AND q.last_result->>'period_start'=from_date::text\n     AND q.last_result->>'period_end'=to_date::text\n     AND NOT EXISTS(SELECT 1 FROM (\n       SELECT s.earned_at FROM public.accounting_cash_rake_sources s\n       WHERE s.club_id=club AND s.recorded_at>q.attempted_at-interval '1 minute' OFFSET 0\n      ) s WHERE s.earned_at>=p_from AND s.earned_at<p_to)\n     AND NOT EXISTS(SELECT 1 FROM (\n       SELECT a.source_id FROM public.accounting_cash_atomic_contract_admissions a\n       WHERE a.admitted_at>q.attempted_at-interval '1 minute' OFFSET 0\n      ) a CROSS JOIN LATERAL (\n       SELECT s.club_id,s.earned_at FROM public.accounting_cash_rake_sources s WHERE s.id=a.source_id OFFSET 0\n      ) s WHERE s.club_id=club AND s.earned_at>=p_from AND s.earned_at<p_to)\n     AND NOT EXISTS(SELECT 1 FROM public.accounting_tournament_fee_sources f\n       WHERE f.club_id=club AND f.charged_at<p_to AND f.recorded_at>q.attempted_at-interval '1 minute')) THEN\n   CONTINUE;\n  END IF;\n  -- SPLIT RECOMPUTE (20261003): inside a chunked close attempt a closed week\n  -- is calculated in parts of its own (fn_rakeback_recompute_split); NULL\n  -- everywhere else, and the whole-period call follows as before.\n  result:=public.fn_rakeback_recompute_split(club,from_date,to_date);\n  IF result->>'status'='in_progress' THEN\n   problems:=problems||jsonb_build_array(jsonb_build_object('club_id',club,'period_start',from_date,'period_end',to_date,\n    'reason','weekly_calculation_in_progress'));\n   CONTINUE;\n  END IF;\n  IF result IS NULL THEN\n  result:=public.fn_rakeback_recompute_periods(club,from_date,to_date,NULL);\n  END IF;\n  ready:=result->>'accounting_version'='2' AND result->>'club_id'=club::text\n   AND result->>'period_start'=from_date::text AND result->>'period_end'=to_date::text\n   AND result->>'status'='ready' AND result->>'request_state'='complete' AND result->>'request_recorded'='true';\n  SELECT EXISTS(SELECT 1 FROM public.accounting_period_recompute_requests q\n   WHERE q.id::text=result->>'request_id' AND q.club_id=club AND q.period_start=from_date AND q.period_end=to_date\n    AND to_jsonb(q.requested_at)=result->'requested_at' AND q.status='complete'\n    AND q.last_result->>'accounting_version'='2' AND q.last_result->>'status'='ready'\n    AND q.last_result->>'club_id'=club::text AND q.last_result->>'period_start'=from_date::text\n    AND q.last_result->>'period_end'=to_date::text) INTO verified;\n  IF ready IS DISTINCT FROM true OR NOT verified THEN\n   problems:=problems||jsonb_build_array(jsonb_build_object('club_id',club,'period_start',from_date,'period_end',to_date,\n    'reason',COALESCE(result->>'reason','weekly_calculation_receipt_not_confirmed')));\n  END IF;\n END LOOP;\n RETURN jsonb_build_object('success',jsonb_array_length(problems)=0,'accounting_version',3,\n  'union_id',p_union_id,'club_id',p_club_id,'period_start',p_from,'period_end',p_to,'clubs',cardinality(clubs),'problems',problems);\nEND $function$\n"},{"metadata":{"oid":"155814172","proacl":["postgres=X/postgres"],"probin":null,"procost":100,"prokind":"f","prolang":"14","proname":"original_inventory_proof_sources_match","prorows":0,"pronargs":0,"proowner":"16384","proconfig":["search_path=pg_catalog"],"proretset":false,"prosecdef":false,"prorettype":"16","prosqlbody":null,"prosupport":"-","proargmodes":null,"proargnames":null,"proargtypes":[],"proisstrict":false,"proparallel":"u","protrftypes":null,"provariadic":"0","provolatile":"s","proleakproof":false,"pronamespace":"24465641","proallargtypes":null,"proargdefaults":null,"pronargdefaults":0},"signature":"smarter_private.original_inventory_proof_sources_match()","definition":"CREATE OR REPLACE FUNCTION smarter_private.original_inventory_proof_sources_match()\n RETURNS boolean\n LANGUAGE sql\n STABLE\n SET search_path TO 'pg_catalog'\nAS $function$\n SELECT count(*)=65 AND bool_and(p.oid IS NOT NULL AND p.proowner='postgres'::regrole AND md5(pg_get_functiondef(p.oid)) IS NOT DISTINCT FROM x.body_md5)\n FROM(VALUES ('public.fn_union_pnl_inventory_state(timestamptz,timestamptz)','d77f5ad055ee433875efed7fd53bd25a'),('public.fn_union_pnl_inventory_population(timestamptz,timestamptz)','449f6f13feefe0d7e26e767a3465bc67'),('public.fn_union_pnl_inventory_as_of(timestamptz)','85513ff85d2b37ad04b79f89e125f1aa'),('smarter_private.original_retirement_boundary_proof(jsonb,timestamptz,timestamptz)','56457798f46f7c06a32b0e52915740a0'),('smarter_private.original_paired_seat_restoration_proof(jsonb,jsonb,timestamptz,timestamptz)','ada80c7f667ca7dad36cf223c80c3a6a'),('smarter_private.original_closed_tournament_rails_proof(jsonb,timestamptz)','a9319182a566e9917353765c414a1aa1'),('smarter_private.original_closed_player_proof(jsonb,timestamptz,timestamptz)','a441c3abe887cc4528268e347916d236'),('smarter_private.original_continued_chair_proof(jsonb,timestamptz,timestamptz)','8876018a8370a99f4012696cb264c740'),('smarter_private.original_returned_cash_base_proof(jsonb,timestamptz,timestamptz)','7ed06b6ccded0d6eb2bc3357742e360d'),('smarter_private.original_erased_cash_base_proof(jsonb,timestamptz)','a2d5ac28a5f07929ed99d6e871dddfa2'),('smarter_private.original_inventory_source_ref_md5(jsonb)','81fba77f13564999931e8a7a47cbd609'),('smarter_private.original_inventory_finite_witness(bigint)','0ef0a8a5b9e85633cf4bf8b0cd15c8d7'),('smarter_private.original_inventory_finite_family_proof(text,jsonb,timestamptz,timestamptz)','dd7861e20f4c90567a704cb2625962b8'),('smarter_private.original_erased_cash_base_request(bigint,text)','1467e44cc7f7871b34eff07f7038019d'),('public.fn_union_pnl_satellite_seat_owner(uuid,uuid)','3beddbfe1e3d204d1907b428d9358f08'),('public.fn_platform_frozen()','ec683805e052fceeae74789e82dce4cc'),('public.fn_active_maintenance_release_boundary()','05b537b57